def delete_issue(connection_id, issue_key, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0413000" if __import__("os").path.isdir("./environment_mix/0413000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_issue"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat()

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _load_cfg():
        cfg = _load("jira_server_config.json")
        if isinstance(cfg, list):
            cfg = cfg[0] if cfg else {}
        return cfg if isinstance(cfg, dict) else {}

    def _get_logs():
        logs = _load("jira_request_logs.json")
        return logs if isinstance(logs, list) else []

    def _save_logs(logs):
        _save("jira_request_logs.json", logs)

    def _check_limits(logs):
        cfg = _load_cfg()
        rate_per_min = cfg.get("rate_limit_per_minute", 120)
        daily_quota = cfg.get("daily_quota_requests", 20000)
        now = _now()
        if isinstance(rate_per_min, int) and rate_per_min >= 0:
            cutoff = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = _parse_ts(r.get("timestamp") or r.get("created_at") or r.get("ts"))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= rate_per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rate_per_min, window_seconds=60)
        if isinstance(daily_quota, int) and daily_quota >= 0:
            today = now.date()
            cnt = 0
            for r in logs:
                ts = _parse_ts(r.get("timestamp") or r.get("created_at") or r.get("ts"))
                if ts and ts.date() == today:
                    cnt += 1
            if cnt >= daily_quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota=daily_quota, window="day")
        return None

    def _log(logs, status, connection_used=None, extra=None):
        row = {
            "id": "jmcp_req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "connection_id": connection_used,
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save_logs(logs)

    # Validate inputs
    if not isinstance(connection_id, str) or not re.match(r"^jmcp_con_[0-9A-Z]{18,}$", connection_id):
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", None, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "Invalid connection_id format.", connection_id=connection_id)
        _log(logs, "error", None, {"error_code": err["error"]["code"]})
        return err
    if not isinstance(issue_key, str) or not issue_key.strip():
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "issue_key is required.", issue_key=issue_key)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err
    issue_key = issue_key.strip().upper()
    if not re.match(r"^[A-Z][A-Z0-9_]+-[0-9]+$", issue_key):
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "Invalid issue_key format.", issue_key=issue_key)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    logs = _get_logs()
    limit_err = _check_limits(logs)
    if limit_err:
        _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
        return limit_err

    # Authorize: connection must exist (deterministic; no ambient auth param)
    conns = _load("jira_connections.json")
    conns = conns if isinstance(conns, list) else []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn:
        err = _err("UNAUTHORIZED", "Connection is not accessible for caller.", connection_id=connection_id)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    issues = _load("jira_issues.json")
    issues = issues if isinstance(issues, list) else []

    idx = None
    issue = None
    for i, r in enumerate(issues):
        if isinstance(r, dict) and r.get("connection_id") == connection_id and (r.get("issue_key") or "").upper() == issue_key:
            idx = i
            issue = r
            break

    if issue is None:
        # Treat as not found locally; per spec we would "delete in Jira first", but offline store can't.
        err = _err("NOT_FOUND", "Issue not found.", issue_key=issue_key)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    # Idempotent delete: if already deleted, succeed with no mutation
    if issue.get("status") == "deleted":
        _log(logs, "ok", connection_id, {"result": "already_deleted", "issue_key": issue_key})
        return {"issue": issue, "deleted": True, "idempotent": True}

    # Enforce lifecycle transition
    if issue.get("status") not in ("active", "archived"):
        err = _err("INVALID_TRANSITION", "Issue cannot be deleted from current status.", from_status=issue.get("status"), to_status="deleted", issue_key=issue_key)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    now_iso = _now_iso()
    mutated = dict(issue)
    mutated["status"] = "deleted"
    mutated["updated_at"] = now_iso
    mutated["last_synced_at"] = now_iso
    # we don't know Jira deleted timestamp; keep jira_updated_at if exists
    issues[idx] = mutated
    _save("jira_issues.json", issues)

    _log(logs, "ok", connection_id, {"result": "deleted", "issue_key": issue_key})
    return {"issue": mutated, "deleted": True, "idempotent": False}

def get_issues(connection_id, project_key, include_subtasks=None, status=None, issue_type_id=None, assignee_account_id=None, reporter_account_id=None, parent_issue_key=None, cursor=None, limit=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0413000" if __import__("os").path.isdir("./environment_mix/0413000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log(tool, conn_id, status_s, started_at, error_code=None):
        try:
            logs = _load("jira_request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int(max(0, (time.time() - started_at) * 1000))
            logs.append({
                "id": f"jlog_{int(time.time()*1000)}_{os.getpid()}",
                "tool": tool,
                "connection_id": conn_id,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "ts": _now()
            })
            _save("jira_request_logs.json", logs)
        except Exception:
            return

    def _encode_cursor(offset):
        payload = json.dumps({"o": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            o = obj.get("o")
            if isinstance(o, int) and o >= 0:
                return o
            return None
        except Exception:
            return None

    started = time.time()

    # Validate inputs
    if not isinstance(connection_id, str):
        _ensure_request_log("get_issues", None, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "connection_id must be a string")
    if not re.match(r"^jmcp_con_[0-9A-Z]{18,}$", connection_id or ""):
        _ensure_request_log("get_issues", connection_id, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "connection_id has invalid format")

    if not isinstance(project_key, str) or not project_key.strip():
        _ensure_request_log("get_issues", connection_id, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_key is required")
    project_key = project_key.strip()

    if include_subtasks is None:
        include_subtasks = True
    if not isinstance(include_subtasks, bool):
        _ensure_request_log("get_issues", connection_id, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_subtasks must be a boolean")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted", "archived"):
            _ensure_request_log("get_issues", connection_id, "error", started, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status filter")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _ensure_request_log("get_issues", connection_id, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if sort is None:
        sort = "updated_at"
    if sort not in ("updated_at", "created_at", "jira_updated_at", "issue_key"):
        _ensure_request_log("get_issues", connection_id, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort value")

    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _ensure_request_log("get_issues", connection_id, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order value")

    off = _decode_cursor(cursor)
    if off is None:
        _ensure_request_log("get_issues", connection_id, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor")

    # Resolve connection
    conns = _load("jira_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn:
        _ensure_request_log("get_issues", connection_id, "error", started, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible Jira connection for the provided connection_id")
    if conn.get("status") != "active":
        _ensure_request_log("get_issues", connection_id, "error", started, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Jira connection is not active")

    issues = _load("jira_issues.json")
    if not isinstance(issues, list):
        issues = []

    # Base filter: connection + project
    base = [r for r in issues if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("project_key") == project_key]

    # Subtask inclusion rule:
    # - If include_subtasks=False: exclude is_subtask rows.
    # - If parent_issue_key filter is provided: return only matching subtasks (regardless of include_subtasks? still requires subtasks)
    if parent_issue_key is not None:
        if not isinstance(parent_issue_key, str) or not parent_issue_key.strip():
            _ensure_request_log("get_issues", connection_id, "error", started, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_issue_key must be a non-empty string when provided")
        parent_issue_key = parent_issue_key.strip()
        base = [r for r in base if r.get("parent_issue_key") == parent_issue_key]
    else:
        if not include_subtasks:
            base = [r for r in base if not r.get("is_subtask")]

    # "must include subtasks by returning rows with parent_issue_key referencing an issue in the same project"
    # When include_subtasks=True and no parent filter, ensure any returned subtask references a parent in same project set.
    if include_subtasks and parent_issue_key is None:
        parent_keys = {r.get("issue_key") for r in base if isinstance(r.get("issue_key"), str) and not r.get("is_subtask")}
        base = [r for r in base if (not r.get("is_subtask")) or (r.get("parent_issue_key") in parent_keys)]

    # Additional filters
    if status is not None:
        base = [r for r in base if r.get("status") == status]
    if issue_type_id is not None:
        if not isinstance(issue_type_id, str):
            _ensure_request_log("get_issues", connection_id, "error", started, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "issue_type_id must be a string")
        base = [r for r in base if r.get("issue_type_id") == issue_type_id]
    if assignee_account_id is not None:
        if not isinstance(assignee_account_id, str):
            _ensure_request_log("get_issues", connection_id, "error", started, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "assignee_account_id must be a string")
        base = [r for r in base if r.get("assignee_account_id") == assignee_account_id]
    if reporter_account_id is not None:
        if not isinstance(reporter_account_id, str):
            _ensure_request_log("get_issues", connection_id, "error", started, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "reporter_account_id must be a string")
        base = [r for r in base if r.get("reporter_account_id") == reporter_account_id]

    # Sort
    reverse = (order == "desc")

    def _sort_key(r):
        v = r.get(sort)
        # ISO timestamps sort lexicographically; None goes last.
        if v is None:
            return ("~", "") if not reverse else ("", "")
        if isinstance(v, str):
            return ("0", v)
        return ("0", str(v))

    base.sort(key=_sort_key, reverse=reverse)

    total = len(base)
    page = base[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _ensure_request_log("get_issues", connection_id, "ok", started)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
            "project_key": project_key,
            "include_subtasks": include_subtasks
        }
    }

def update_issue(connection_id, issue_key, summary=None, description=None, assignee_account_id=None, reporter_account_id=None, parent_issue_key=None, fields_json=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0413000" if __import__("os").path.isdir("./environment_mix/0413000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_issue"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat()

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _load_cfg():
        cfg = _load("jira_server_config.json")
        if isinstance(cfg, list):
            cfg = cfg[0] if cfg else {}
        return cfg if isinstance(cfg, dict) else {}

    def _get_logs():
        logs = _load("jira_request_logs.json")
        return logs if isinstance(logs, list) else []

    def _save_logs(logs):
        _save("jira_request_logs.json", logs)

    def _check_limits(logs):
        cfg = _load_cfg()
        rate_per_min = cfg.get("rate_limit_per_minute", 120)
        daily_quota = cfg.get("daily_quota_requests", 20000)
        now = _now()
        if isinstance(rate_per_min, int) and rate_per_min >= 0:
            cutoff = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = _parse_ts(r.get("timestamp") or r.get("created_at") or r.get("ts"))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= rate_per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rate_per_min, window_seconds=60)
        if isinstance(daily_quota, int) and daily_quota >= 0:
            today = now.date()
            cnt = 0
            for r in logs:
                ts = _parse_ts(r.get("timestamp") or r.get("created_at") or r.get("ts"))
                if ts and ts.date() == today:
                    cnt += 1
            if cnt >= daily_quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota=daily_quota, window="day")
        return None

    def _log(logs, status, connection_used=None, extra=None):
        row = {
            "id": "jmcp_req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "connection_id": connection_used,
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save_logs(logs)

    # Validate inputs
    if not isinstance(connection_id, str) or not re.match(r"^jmcp_con_[0-9A-Z]{18,}$", connection_id):
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", None, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "Invalid connection_id format.", connection_id=connection_id)
        _log(logs, "error", None, {"error_code": err["error"]["code"]})
        return err
    if not isinstance(issue_key, str) or not issue_key.strip():
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "issue_key is required.", issue_key=issue_key)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err
    issue_key = issue_key.strip().upper()
    if not re.match(r"^[A-Z][A-Z0-9_]+-[0-9]+$", issue_key):
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "Invalid issue_key format.", issue_key=issue_key)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    updatable = {
        "summary": summary,
        "description": description,
        "assignee_account_id": assignee_account_id,
        "reporter_account_id": reporter_account_id,
        "parent_issue_key": parent_issue_key,
        "fields_json": fields_json,
    }
    provided = {k: v for k, v in updatable.items() if v is not None}
    if not provided:
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "No updatable fields provided.")
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    if fields_json is not None and not isinstance(fields_json, dict):
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "fields_json must be an object.", fields_json_type=type(fields_json).__name__)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    if parent_issue_key is not None:
        if not isinstance(parent_issue_key, str) or not re.match(r"^[A-Z][A-Z0-9_]+-[0-9]+$", parent_issue_key.strip().upper()):
            logs = _get_logs()
            limit_err = _check_limits(logs)
            if limit_err:
                _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
                return limit_err
            err = _err("VALIDATION_ERROR", "Invalid parent_issue_key format.", parent_issue_key=parent_issue_key)
            _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
            return err
        parent_issue_key = parent_issue_key.strip().upper()

    logs = _get_logs()
    limit_err = _check_limits(logs)
    if limit_err:
        _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
        return limit_err

    # Authorize: connection must exist
    conns = _load("jira_connections.json")
    conns = conns if isinstance(conns, list) else []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn:
        err = _err("UNAUTHORIZED", "Connection is not accessible for caller.", connection_id=connection_id)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    issues = _load("jira_issues.json")
    issues = issues if isinstance(issues, list) else []

    idx = None
    issue = None
    for i, r in enumerate(issues):
        if isinstance(r, dict) and r.get("connection_id") == connection_id and (r.get("issue_key") or "").upper() == issue_key:
            idx = i
            issue = r
            break

    if issue is None:
        err = _err("NOT_FOUND", "Issue not found.", issue_key=issue_key)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    if issue.get("status") == "deleted":
        err = _err("INVALID_TRANSITION", "Cannot update a deleted issue.", issue_key=issue_key, status="deleted")
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    # Apply updates
    now_iso = _now_iso()
    mutated = dict(issue)

    if summary is not None:
        if not isinstance(summary, str):
            err = _err("VALIDATION_ERROR", "summary must be a string.", summary_type=type(summary).__name__)
            _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
            return err
        mutated["summary"] = summary
    if description is not None:
        if not isinstance(description, str):
            err = _err("VALIDATION_ERROR", "description must be a string.", description_type=type(description).__name__)
            _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
            return err
        mutated["description"] = description
    if assignee_account_id is not None:
        if not isinstance(assignee_account_id, str) or not assignee_account_id.strip():
            err = _err("VALIDATION_ERROR", "assignee_account_id must be a non-empty string.", assignee_account_id=assignee_account_id)
            _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
            return err
        mutated["assignee_account_id"] = assignee_account_id
    if reporter_account_id is not None:
        if not isinstance(reporter_account_id, str) or not reporter_account_id.strip():
            err = _err("VALIDATION_ERROR", "reporter_account_id must be a non-empty string.", reporter_account_id=reporter_account_id)
            _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
            return err
        mutated["reporter_account_id"] = reporter_account_id

    if parent_issue_key is not None:
        # When setting a parent, mark as subtask and enforce rule
        mutated["parent_issue_key"] = parent_issue_key
        mutated["is_subtask"] = True

    if fields_json is not None:
        mutated["fields_json"] = fields_json

    # Enforce constraint: if is_subtask true then parent_issue_key not null
    if bool(mutated.get("is_subtask")) and not mutated.get("parent_issue_key"):
        err = _err("VALIDATION_ERROR", "If is_subtask is true then parent_issue_key is required.", issue_key=issue_key)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    mutated["updated_at"] = now_iso
    mutated["jira_updated_at"] = now_iso
    mutated["last_synced_at"] = now_iso

    issues[idx] = mutated
    _save("jira_issues.json", issues)

    _log(logs, "ok", connection_id, {"result": "updated", "issue_key": issue_key})
    return {"issue": mutated}

def list_fields(connection_id, status=None, cursor=None, limit=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0413000" if __import__("os").path.isdir("./environment_mix/0413000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log(tool, conn_id, status_s, started_at, error_code=None):
        try:
            logs = _load("jira_request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int(max(0, (time.time() - started_at) * 1000))
            logs.append({
                "id": f"jlog_{int(time.time()*1000)}_{os.getpid()}",
                "tool": tool,
                "connection_id": conn_id,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "ts": _now()
            })
            _save("jira_request_logs.json", logs)
        except Exception:
            return

    def _encode_cursor(offset):
        payload = json.dumps({"o": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            o = obj.get("o")
            if isinstance(o, int) and o >= 0:
                return o
            return None
        except Exception:
            return None

    started = time.time()

    # Validate inputs
    if not isinstance(connection_id, str):
        _ensure_request_log("list_fields", None, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "connection_id must be a string")
    if not re.match(r"^jmcp_con_[0-9A-Z]{18,}$", connection_id or ""):
        _ensure_request_log("list_fields", connection_id, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "connection_id has invalid format")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deprecated"):
            _ensure_request_log("list_fields", connection_id, "error", started, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status")

    if limit is None:
        limit = 200
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        _ensure_request_log("list_fields", connection_id, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")

    if sort is None:
        sort = "name"
    if sort not in ("name", "key", "updated_at", "created_at"):
        _ensure_request_log("list_fields", connection_id, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _ensure_request_log("list_fields", connection_id, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order")

    off = _decode_cursor(cursor)
    if off is None:
        _ensure_request_log("list_fields", connection_id, "error", started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor")

    # Resolve connection
    conns = _load("jira_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn:
        _ensure_request_log("list_fields", connection_id, "error", started, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible Jira connection for the provided connection_id")
    if conn.get("status") != "active":
        _ensure_request_log("list_fields", connection_id, "error", started, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Jira connection is not active")

    # Staleness / cached marker (implementation-defined: >24h)
    cached = True
    stale = False
    mlsa = conn.get("metadata_last_synced_at")
    if isinstance(mlsa, str) and mlsa:
        try:
            # Parse basic ISO-ish; if fails, treat stale
            dt = datetime.datetime.fromisoformat(mlsa.replace("Z", "+00:00"))
            age = datetime.datetime.now(datetime.timezone.utc) - dt.astimezone(datetime.timezone.utc)
            stale = age.total_seconds() > 24 * 3600
        except Exception:
            stale = True
    else:
        stale = True

    # Offline datastore: cannot refresh from Jira; we keep cached=true and indicate staleness.
    meta = _load("jira_metadata.json")
    if not isinstance(meta, list):
        meta = []

    rows = [r for r in meta if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("kind") == "field"]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    reverse = (order == "desc")

    def _sort_key(r):
        v = r.get(sort)
        # Put None last regardless of order using a tuple prefix.
        if v is None:
            return ("~", "") if not reverse else ("", "")
        if isinstance(v, str):
            return ("0", v.lower() if sort in ("name", "key") else v)
        return ("0", str(v))

    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _ensure_request_log("list_fields", connection_id, "ok", started)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
            "cached": cached,
            "stale": stale,
            "metadata_last_synced_at": mlsa
        }
    }

