    def _sort_key(r):
        v = r.get(sort)
        if v is None:
            # allow stable sorting with None at end
            return (1, "")
        if isinstance(v, str):
            return (0, v.lower())
        return (0, str(v))

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    if start + limit < total:
        enc = f"v1:{connection_id}:{start + limit}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(enc).decode("utf-8").rstrip("=")

    _log(200)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None,
            "sort": sort,
            "order": order,
        },
    }

