def get_user(connection_id, email, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0413000" if __import__("os").path.isdir("./environment_mix/0413000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_user"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, error_code=None, message=None):
        logs = _load("jira_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"jmcp_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "connection_id": connection_id,
            "status": "error" if status_code >= 400 else "ok",
            "http_status": status_code,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("jira_request_logs.json", logs)

    # Validation
    if not isinstance(connection_id, str) or not re.match(r"^jmcp_con_[0-9A-Z]{18,}$", connection_id):
        _log(400, "VALIDATION_ERROR", "Invalid connection_id.")
        return _err("VALIDATION_ERROR", "Invalid connection_id.", field="connection_id")

    if not isinstance(email, str) or not email.strip():
        _log(400, "VALIDATION_ERROR", "Email is required.")
        return _err("VALIDATION_ERROR", "Email is required.", field="email")

    norm_email = email.strip().lower()
    # Simple email sanity check
    if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", norm_email):
        _log(400, "VALIDATION_ERROR", "Invalid email format.")
        return _err("VALIDATION_ERROR", "Invalid email format.", field="email")

    # Auth / connection resolution
    conns = _load("jira_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn or conn.get("status") != "active":
        _log(401, "UNAUTHORIZED", "Connection not accessible.")
        return _err("UNAUTHORIZED", "Connection not accessible for caller.", connection_id=connection_id)

    users = _load("jira_directory_users.json")
    if not isinstance(users, list):
        users = []

    now = _now_iso()

    # Try cache hit
    hit = next((u for u in users if isinstance(u, dict) and u.get("connection_id") == connection_id and u.get("email") == norm_email), None)
    if hit and hit.get("status") in ("active", "inactive") and isinstance(hit.get("account_id"), str) and len(hit.get("account_id")) >= 3:
        hit = dict(hit)
        hit["last_seen_at"] = now
        hit["updated_at"] = now
        # persist last_seen_at update
        for i, u in enumerate(users):
            if isinstance(u, dict) and u.get("id") == hit.get("id"):
                users[i] = hit
                _save("jira_directory_users.json", users)
                break
        _log(200)
        return {"data": hit}

    # "Query Jira" behavior (offline): deterministically attempt to resolve using existing directory cache
    # by account_id uniqueness; if no match, return NOT_FOUND.
    # If we have a hit but status unknown, we can "upsert" to active if it already has a valid account_id.
    if hit and hit.get("status") == "unknown" and isinstance(hit.get("account_id"), str) and len(hit.get("account_id")) >= 3:
        # transition unknown -> active is allowed
        updated = dict(hit)
        updated["status"] = "active"
        updated["last_seen_at"] = now
        updated["updated_at"] = now
        # enforce uniqueness on (connection_id, account_id)
        for u in users:
            if not isinstance(u, dict):
                continue
            if u.get("id") == updated.get("id"):
                continue
            if u.get("connection_id") == connection_id and u.get("account_id") == updated.get("account_id"):
                _log(409, "CONFLICT", "Unique constraint violation on (connection_id, account_id).")
                return _err("CONFLICT", "User conflict for this connection.", constraint="unique(connection_id, account_id)")
        for i, u in enumerate(users):
            if isinstance(u, dict) and u.get("id") == updated.get("id"):
                users[i] = updated
                _save("jira_directory_users.json", users)
                _log(200)
                return {"data": updated}

    # No resolvable user found: NOT_FOUND (as per tool description/business rule)
    _log(404, "NOT_FOUND", "No Jira user could be resolved for this email.")
    return _err("NOT_FOUND", "No Jira user could be resolved for the provided email in this connection.", email=norm_email, connection_id=connection_id)

def create_issue(connection_id, project_key, summary, issue_type_id, description=None, reporter_account_id=None, assignee_account_id=None, parent_issue_key=None, fields_json=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0413000" if __import__("os").path.isdir("./environment_mix/0413000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_issue"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _load_cfg():
        cfg = _load("jira_server_config.json")
        if isinstance(cfg, list):
            cfg = cfg[0] if cfg else {}
        return cfg if isinstance(cfg, dict) else {}

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _check_limits(logs):
        cfg = _load_cfg()
        rate_per_min = cfg.get("rate_limit_per_minute", 120)
        daily_quota = cfg.get("daily_quota_requests", 20000)
        now = datetime.datetime.now(datetime.timezone.utc)
        if isinstance(rate_per_min, int) and rate_per_min >= 0:
            cutoff = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = _parse_ts(r.get("created_at") or r.get("ts"))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= rate_per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rate_per_min, window_seconds=60)
        if isinstance(daily_quota, int) and daily_quota >= 0:
            today = now.date()
            cnt = 0
            for r in logs:
                ts = _parse_ts(r.get("created_at") or r.get("ts"))
                if ts and ts.date() == today:
                    cnt += 1
            if cnt >= daily_quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota=daily_quota, window="day")
        return None

    def _append_log(status, http_status, error_code=None, message=None, extra=None):
        logs = _load("jira_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs2 = _load("jira_request_log.json")
        if not isinstance(logs2, list):
            logs2 = []
        row = {
            "id": f"jmcp_req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+len(logs2)+1}",
            "endpoint": endpoint,
            "connection_id": connection_id,
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
            "extra": extra or {}
        }
        logs.append(row)
        logs2.append(row)
        _save("jira_request_logs.json", logs)
        _save("jira_request_log.json", logs2)

    logs = _load("jira_request_logs.json")
    if not isinstance(logs, list):
        logs = []
    logs_alt = _load("jira_request_log.json")
    if isinstance(logs_alt, list):
        logs = logs + logs_alt
    limit_err = _check_limits(logs)
    if limit_err:
        _append_log("error", 429, limit_err["error"]["code"], limit_err["error"]["message"])
        return limit_err

    # Validation
    if not isinstance(connection_id, str) or not re.match(r"^jmcp_con_[0-9A-Z]{18,}$", connection_id or ""):
        _append_log("error", 400, "VALIDATION_ERROR", "Invalid connection_id.", {"field": "connection_id"})
        return _err("VALIDATION_ERROR", "Invalid connection_id.", field="connection_id")
    if not isinstance(project_key, str) or not project_key.strip():
        _append_log("error", 400, "VALIDATION_ERROR", "project_key is required.", {"field": "project_key"})
        return _err("VALIDATION_ERROR", "project_key is required.", field="project_key")
    if not isinstance(summary, str) or not summary.strip():
        _append_log("error", 400, "VALIDATION_ERROR", "summary is required.", {"field": "summary"})
        return _err("VALIDATION_ERROR", "summary is required.", field="summary")
    if not isinstance(issue_type_id, str) or not issue_type_id.strip():
        _append_log("error", 400, "VALIDATION_ERROR", "issue_type_id is required.", {"field": "issue_type_id"})
        return _err("VALIDATION_ERROR", "issue_type_id is required.", field="issue_type_id")
    if fields_json is not None and not isinstance(fields_json, dict):
        _append_log("error", 400, "VALIDATION_ERROR", "fields_json must be an object.", {"field": "fields_json"})
        return _err("VALIDATION_ERROR", "fields_json must be an object.", field="fields_json")
    if parent_issue_key is not None:
        if not isinstance(parent_issue_key, str) or not parent_issue_key.strip():
            _append_log("error", 400, "VALIDATION_ERROR", "parent_issue_key must be a non-empty string when provided.", {"field": "parent_issue_key"})
            return _err("VALIDATION_ERROR", "parent_issue_key must be a non-empty string when provided.", field="parent_issue_key")
        pk = parent_issue_key.strip()
        if not re.match(r"^[A-Z][A-Z0-9_]+-[0-9]+$", pk):
            _append_log("error", 400, "VALIDATION_ERROR", "parent_issue_key has invalid format.", {"field": "parent_issue_key"})
            return _err("VALIDATION_ERROR", "parent_issue_key has invalid format.", field="parent_issue_key")

    # Resolve connection
    conns = _load("jira_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn_row = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == connection_id:
            conn_row = c
            break
    if conn_row is None:
        _append_log("error", 404, "NOT_FOUND", "Connection not found.", {"connection_id": connection_id})
        return _err("NOT_FOUND", "Connection not found.", connection_id=connection_id)
    if conn_row.get("status") != "active":
        active = [c for c in conns if isinstance(c, dict) and c.get("status") == "active"]
        if len(active) == 1:
            conn_row = active[0]
            connection_id = conn_row.get("id")
        else:
            _append_log("error", 401, "UNAUTHORIZED", "No accessible active Jira connection available.")
            return _err("UNAUTHORIZED", "No accessible active Jira connection available.")

    project_key = project_key.strip()
    summary = summary.strip()
    issue_type_id = issue_type_id.strip()

    # Determine next issue key number (simulate Jira create)
    issues = _load("jira_issues.json")
    if not isinstance(issues, list):
        issues = []
    max_n = 0
    for r in issues:
        if not isinstance(r, dict):
            continue
        if r.get("connection_id") != connection_id:
            continue
        ik = r.get("issue_key")
        if isinstance(ik, str) and ik.startswith(project_key + "-"):
            try:
                n = int(ik.split("-", 1)[1])
                if n > max_n:
                    max_n = n
            except Exception:
                pass
    new_num = max_n + 1 if max_n > 0 else random.randint(100, 999)  # keep plausible if no history
    new_issue_key = f"{project_key}-{new_num}"

    # Ensure uniqueness within connection
    existing_keys = {r.get("issue_key") for r in issues if isinstance(r, dict) and r.get("connection_id") == connection_id}
    while new_issue_key in existing_keys:
        new_num += 1
        new_issue_key = f"{project_key}-{new_num}"

    # Generate Jira issue id (simulate)
    existing_jira_ids = {r.get("jira_issue_id") for r in issues if isinstance(r, dict) and r.get("connection_id") == connection_id}
    base = int(time.time() * 1000)
    jira_issue_id = str(base)
    while jira_issue_id in existing_jira_ids:
        base += 1
        jira_issue_id = str(base)

    now = _now_iso()
    new_row = {
        "id": f"jmcp_iss_{int(time.time()*1000)}_{os.getpid()}_{len(issues)+1}",
        "connection_id": connection_id,
        "status": "active",
        "jira_issue_id": jira_issue_id,
        "issue_key": new_issue_key,
        "project_key": project_key,
        "issue_type_id": issue_type_id,
        "summary": summary,
        "description": description if isinstance(description, str) or description is None else str(description),
        "reporter_account_id": reporter_account_id.strip() if isinstance(reporter_account_id, str) and reporter_account_id.strip() else None,
        "assignee_account_id": assignee_account_id.strip() if isinstance(assignee_account_id, str) and assignee_account_id.strip() else None,
        "parent_issue_key": parent_issue_key.strip() if isinstance(parent_issue_key, str) and parent_issue_key.strip() else None,
        "is_subtask": bool(parent_issue_key.strip()) if isinstance(parent_issue_key, str) else False,
        "fields_json": fields_json if isinstance(fields_json, dict) else None,
        "jira_updated_at": now,
        "last_synced_at": now,
        "created_at": now,
        "updated_at": now,
    }

    # Constraint: if is_subtask true then parent_issue_key not null
    if new_row["is_subtask"] and not new_row["parent_issue_key"]:
        _append_log("error", 400, "VALIDATION_ERROR", "If is_subtask is true then parent_issue_key must be set.")
        return _err("VALIDATION_ERROR", "If is_subtask is true then parent_issue_key must be set.", rule="if is_subtask = true then parent_issue_key is not null")

    # Constraint: issue_key pattern
    if not re.match(r"^[A-Z][A-Z0-9_]+-[0-9]+$", new_row["issue_key"]):
        _append_log("error", 400, "VALIDATION_ERROR", "Generated issue_key has invalid format.", issue_key=new_row["issue_key"])
        return _err("VALIDATION_ERROR", "Generated issue_key has invalid format.", issue_key=new_row["issue_key"])

    issues.append(new_row)
    _save("jira_issues.json", issues)

    _append_log("ok", 201, None, None)
    return {"issue": new_row}

