    def _log(logs, status, connection_used=None, extra=None):
        row = {
            "id": "jmcp_req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "connection_id": connection_used,
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save_logs(logs)

    # Validate inputs
    if not isinstance(connection_id, str) or not re.match(r"^jmcp_con_[0-9A-Z]{18,}$", connection_id):
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", None, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "Invalid connection_id format.", connection_id=connection_id)
        _log(logs, "error", None, {"error_code": err["error"]["code"]})
        return err

    for nm, val in [("link_type_name", link_type_name), ("inward_issue_key", inward_issue_key), ("outward_issue_key", outward_issue_key)]:
        if not isinstance(val, str) or not val.strip():
            logs = _get_logs()
            limit_err = _check_limits(logs)
            if limit_err:
                _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
                return limit_err
            err = _err("VALIDATION_ERROR", f"{nm} is required.")
