        if limit_err:
            _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "inward_issue_key must not equal outward_issue_key.", inward_issue_key=inward_issue_key, outward_issue_key=outward_issue_key)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    if not re.match(r"^[A-Z][A-Z0-9_]+-[0-9]+$", inward_issue_key):
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
