    if comment is not None and not isinstance(comment, str):
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "comment must be a string.", comment_type=type(comment).__name__)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    logs = _get_logs()
    limit_err = _check_limits(logs)
    if limit_err:
        _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
        return limit_err

    # Authorize: connection must exist
    conns = _load("jira_connections.json")
    conns = conns if isinstance(conns, list) else []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn:
        err = _err("UNAUTHORIZED", "Connection is not accessible for caller.", connection_id=connection_id)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    # Enforce link_type_name exists and active for this connection
    metas = _load("jira_metadata.json")
    metas = metas if isinstance(metas, list) else []
    has_link_type = any(
        isinstance(m, dict)
        and m.get("connection_id") == connection_id
        and m.get("kind") == "link_type"
        and m.get("status") == "active"
        and m.get("name") == link_type_name
        for m in metas
    )
    if not has_link_type:
        err = _err("VALIDATION_ERROR", "link_type_name must exist in active link types for this connection.", link_type_name=link_type_name, connection_id=connection_id)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    issues = _load("jira_issues.json")
    issues = issues if isinstance(issues, list) else []
    def _issue_exists(key):
        for r in issues:
            if isinstance(r, dict) and r.get("connection_id") == connection_id and (r.get("issue_key") or "").upper() == key and r.get("status") != "deleted":
                return True
        return False

    if not _issue_exists(inward_issue_key):
