        return err

    links = _load("jira_issue_links.json")
    links = links if isinstance(links, list) else []

    # Enforce uniqueness for active link
    for r in links:
        if not isinstance(r, dict):
            continue
        if r.get("connection_id") == connection_id and r.get("status") == "active" and r.get("link_type_name") == link_type_name and (r.get("inward_issue_key") or "").upper() == inward_issue_key and (r.get("outward_issue_key") or "").upper() == outward_issue_key:
