        if limit_err:
            _log(logs, "error", None, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "Invalid connection_id format.", connection_id=connection_id)
        _log(logs, "error", None, {"error_code": err["error"]["code"]})
        return err

    if not isinstance(issue_key, str) or not issue_key.strip():
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "issue_key is required.", issue_key=issue_key)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    issue_key = issue_key.strip().upper()
    if not re.match(r"^[A-Z][A-Z0-9_]+-[0-9]+$", issue_key):
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "Invalid issue_key format.", issue_key=issue_key)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    if refresh is not None and not isinstance(refresh, bool):
        logs = _get_logs()
        limit_err = _check_limits(logs)
        if limit_err:
            _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
            return limit_err
        err = _err("VALIDATION_ERROR", "refresh must be a boolean.", refresh_type=type(refresh).__name__)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    logs = _get_logs()
    limit_err = _check_limits(logs)
    if limit_err:
        _log(logs, "error", connection_id, {"error_code": limit_err["error"]["code"]})
        return limit_err

    # Authorize: connection must exist
    conns = _load("jira_connections.json")
    conns = conns if isinstance(conns, list) else []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn:
        err = _err("UNAUTHORIZED", "Connection is not accessible for caller.", connection_id=connection_id)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    issues = _load("jira_issues.json")
    issues = issues if isinstance(issues, list) else []

    issue = next((r for r in issues if isinstance(r, dict) and r.get("connection_id") == connection_id and (r.get("issue_key") or "").upper() == issue_key), None)
    if not issue:
        err = _err("NOT_FOUND", "Issue not found.", issue_key=issue_key)
        _log(logs, "error", connection_id, {"error_code": err["error"]["code"]})
        return err

    # Refresh behavior: offline implementation marks as cached and optionally bumps last_seen sync time if refresh requested
    cached = True
    if refresh:
        now_iso = _now_iso()
        # Only mutate if this actually changes something observable
        mutated = dict(issue)
        mutated["last_synced_at"] = now_iso
        mutated["updated_at"] = now_iso
        mutated["jira_updated_at"] = now_iso
        # persist mutation
        for i, r in enumerate(issues):
            if isinstance(r, dict) and r.get("id") == issue.get("id"):
                issues[i] = mutated
                _save("jira_issues.json", issues)
                issue = mutated
                cached = False
                break

    _log(logs, "ok", connection_id, {"result": "fetched", "issue_key": issue_key, "cached": cached})
    return {"issue": issue, "cached": cached}

def update_connection(connection_id, status=None, display_name=None, default_project_key=None, auth_secret_ref=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0413000" if __import__("os").path.isdir("./environment_mix/0413000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, code=None, message=None, extra=None):
        logs = _load("jira_request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "jreq_" + uuid.uuid4().hex,
            "endpoint": "update_connection",
            "connection_id": connection_id,
            "status": status_s,
            "error_code": code,
            "error_message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "extra": extra or {}
        })
        _save("jira_request_log.json", logs)

    def _check_rate_limits():
        cfg = _load("jira_server_config.json")
        if isinstance(cfg, list) and cfg:
            cfg = cfg[0]
        if not isinstance(cfg, dict):
            cfg = {}
        rate_per_min = cfg.get("rate_limit_per_minute", 120)
        daily_quota = cfg.get("daily_quota_requests", 20000)

        logs = _load("jira_request_log.json")
        if not isinstance(logs, list):
            logs = []
        cutoff_60 = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        today = datetime.datetime.utcnow().date().isoformat()

        last_min = 0
        today_cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = r.get("created_at")
            if isinstance(ts, str):
                if ts >= cutoff_60:
                    last_min += 1
                if ts[:10] == today:
                    today_cnt += 1

        if isinstance(rate_per_min, int) and rate_per_min >= 0 and last_min >= rate_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rate_per_min, window_seconds=60)
        if isinstance(daily_quota, int) and daily_quota >= 0 and today_cnt >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota=daily_quota, window="day")
        return None

    rl = _check_rate_limits()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    if not isinstance(connection_id, str) or not re.match(r"^jmcp_con_[0-9A-Z]{18,}$", connection_id):
        e = _err("VALIDATION_ERROR", "connection_id is malformed.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    if status is None and display_name is None and default_project_key is None and auth_secret_ref is None:
        e = _err("VALIDATION_ERROR", "No updatable fields provided.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "error"):
            e = _err("VALIDATION_ERROR", "status must be one of: active, disabled, error.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    if display_name is not None and (not isinstance(display_name, str) or not display_name.strip()):
        e = _err("VALIDATION_ERROR", "display_name must be a non-empty string when provided.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if default_project_key is not None and (not isinstance(default_project_key, str) or not default_project_key.strip()):
        e = _err("VALIDATION_ERROR", "default_project_key must be a non-empty string when provided.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if auth_secret_ref is not None and (not isinstance(auth_secret_ref, str) or not auth_secret_ref.strip()):
        e = _err("VALIDATION_ERROR", "auth_secret_ref must be a non-empty string when provided.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    conns = _load("jira_connections.json")
    if not isinstance(conns, list):
        conns = []
    idx = None
    conn = None
    for i, c in enumerate(conns):
        if isinstance(c, dict) and c.get("id") == connection_id:
            idx = i
            conn = c
            break
    if conn is None:
        e = _err("NOT_FOUND", "Connection not found.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # Validate unique(base_url) on updates (base_url not mutable here) and URL validity not needed unless mutating base_url.
    # Lifecycle transition enforcement
    transitions = {
        "active": ("disabled", "error"),
        "disabled": ("active",),
        "error": ("active", "disabled")
    }
    updated = dict(conn)

    if status is not None and status != conn.get("status"):
        cur = conn.get("status")
        if cur not in transitions or status not in transitions[cur]:
            e = _err("INVALID_TRANSITION", "Requested status transition is not allowed.", from_status=cur, to_status=status)
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        updated["status"] = status
        if status == "error":
            # constraint: if status='error' then last_error is not null
            if not updated.get("last_error"):
                updated["last_error"] = "Manually set to error."
        else:
            # allow keeping last_error, but clear when moving out of error to reflect recovery
            if conn.get("status") == "error":
                updated["last_error"] = None

    if display_name is not None:
        updated["display_name"] = display_name.strip()
    if default_project_key is not None:
        updated["default_project_key"] = default_project_key.strip()
    if auth_secret_ref is not None:
        updated["auth_secret_ref"] = auth_secret_ref.strip()

    updated["updated_at"] = now

    conns[idx] = updated
    _save("jira_connections.json", conns)
    _log("ok")
    return {"connection": updated}

def get_whoami(connection_id=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0413000" if __import__("os").path.isdir("./environment_mix/0413000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, code=None, message=None, extra=None):
        logs = _load("jira_request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "jreq_" + uuid.uuid4().hex,
            "endpoint": "get_whoami",
            "connection_id": connection_id,
            "status": status,
            "error_code": code,
            "error_message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "extra": extra or {}
        })
        _save("jira_request_log.json", logs)

    def _check_rate_limits():
        cfg = _load("jira_server_config.json")
        if isinstance(cfg, list) and cfg:
            cfg = cfg[0]
        if not isinstance(cfg, dict):
            cfg = {}
        rate_per_min = cfg.get("rate_limit_per_minute", 120)
        daily_quota = cfg.get("daily_quota_requests", 20000)

        logs = _load("jira_request_log.json")
        if not isinstance(logs, list):
            logs = []
        cutoff_60 = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
        today = datetime.datetime.utcnow().date().isoformat()

        last_min = 0
        today_cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = r.get("created_at")
            if isinstance(ts, str):
                if ts >= cutoff_60:
                    last_min += 1
                if ts[:10] == today:
                    today_cnt += 1

        if isinstance(rate_per_min, int) and rate_per_min >= 0 and last_min >= rate_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rate_per_min, window_seconds=60)
        if isinstance(daily_quota, int) and daily_quota >= 0 and today_cnt >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota=daily_quota, window="day")
        return None

    rl = _check_rate_limits()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    if connection_id is not None:
        if not isinstance(connection_id, str) or not re.match(r"^jmcp_con_[0-9A-Z]{18,}$", connection_id):
            e = _err("VALIDATION_ERROR", "connection_id is malformed.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    conns = _load("jira_connections.json")
    if not isinstance(conns, list):
        conns = []

    cfg = _load("jira_server_config.json")
    if isinstance(cfg, list) and cfg:
        cfg = cfg[0]
    if not isinstance(cfg, dict):
        cfg = {}

    active_conn = None
    if connection_id:
        for c in conns:
            if isinstance(c, dict) and c.get("id") == connection_id:
                active_conn = c
                break
        if not active_conn or active_conn.get("status") != "active":
            e = _err("UNAUTHORIZED", "No valid credential/connection context available for requested connection.")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    else:
        # Determine configured active connection deterministically:
        # 1) config.active_connection_id if set and active
        # 2) if exactly one active connection exists, use it
        # else UNAUTHORIZED (per tool description)
        cfg_id = cfg.get("active_connection_id")
        if isinstance(cfg_id, str):
            for c in conns:
                if isinstance(c, dict) and c.get("id") == cfg_id and c.get("status") == "active":
                    active_conn = c
                    break
        if not active_conn:
            actives = [c for c in conns if isinstance(c, dict) and c.get("status") == "active"]
            if len(actives) == 1:
                active_conn = actives[0]

        if not active_conn:
            e = _err("UNAUTHORIZED", "No active connection is configured for this server.")
            _log("error", e["error"]["code"], e["error"]["message"], extra={"active_count": len([c for c in conns if isinstance(c, dict) and c.get("status") == "active"])})
            return e

    # Compute current consumption
    logs = _load("jira_request_log.json")
    if not isinstance(logs, list):
        logs = []
    cutoff_60 = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    today = datetime.datetime.utcnow().date().isoformat()

    last_min = 0
    today_cnt = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        ts = r.get("created_at")
        if isinstance(ts, str):
            if ts >= cutoff_60:
                last_min += 1
            if ts[:10] == today:
                today_cnt += 1

    rate_per_min = cfg.get("rate_limit_per_minute", 120)
    daily_quota = cfg.get("daily_quota_requests", 20000)

    identity = {
        "subject": "ambient",
        "auth_type": active_conn.get("auth_type"),
        "scopes": cfg.get("scopes") if isinstance(cfg.get("scopes"), list) else ["jira:read", "jira:write"],
        "entitlements": {
            "rate_limit_per_minute": rate_per_min,
            "daily_quota_requests": daily_quota
        },
        "usage": {
            "requests_last_minute": last_min,
            "requests_today": today_cnt
        },
        "active_connection": active_conn
    }

    _log("ok")
    return {"whoami": identity}
